const logoutTitle=document.querySelector('#logout-title'),logoutMessage=document.querySelector('#logout-message'),logoutButton=document.querySelector('#confirm-logout');
let logoutRedirectScheduled=false;
function signedOut(){logoutTitle.textContent='You have been logged out.';logoutMessage.textContent='Your dashboard session has ended. Returning to client QR login...';logoutButton.hidden=true;document.querySelector('#return-login').href='/client-login?loggedout=1';if(!logoutRedirectScheduled){logoutRedirectScheduled=true;setTimeout(()=>location.replace('/client-login?loggedout=1'),1800)}}

async function logoutPage(){if(location.protocol==='file:'){logoutTitle.textContent='Open the running application.';logoutMessage.textContent='Use http://127.0.0.1:3080/logout to sign out. A file preview cannot end a server session.';document.querySelector('#return-login').href='http://127.0.0.1:3080/client';return}try{const response=await fetch('/api/me',{credentials:'same-origin',cache:'no-store'});if(response.status===401){signedOut();return}if(!response.ok&&response.status!==403)throw Error('Unable to check your session. Please try again.');logoutTitle.textContent='Ready to sign out?';logoutMessage.textContent='End your dashboard session on this device.';logoutButton.hidden=false;logoutButton.onclick=async()=>{logoutButton.disabled=true;try{const result=await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'});if(!result.ok)throw Error('Sign out failed. Please try again.');signedOut()}catch(e){logoutMessage.textContent=e.message}finally{logoutButton.disabled=false}}}catch(e){logoutTitle.textContent='Could not check your session.';logoutMessage.textContent=e.message}}
logoutPage();
